-- City-name corrections (Kyrgyz name_kg + Дж→Ж). Idempotent; safe to re-run.
BEGIN;
-- 1) Дж -> Ж across all name fields
UPDATE cities SET
  name_ru=replace(replace(name_ru,'Дж','Ж'),'дж','ж'),
  name_kg=replace(replace(name_kg,'Дж','Ж'),'дж','ж'),
  region_name_ru=replace(replace(coalesce(region_name_ru,''),'Дж','Ж'),'дж','ж'),
  region_name_kg=replace(replace(coalesce(region_name_kg,''),'Дж','Ж'),'дж','ж'),
  district_name_ru=replace(replace(coalesce(district_name_ru,''),'Дж','Ж'),'дж','ж'),
  district_name_kg=replace(replace(coalesce(district_name_kg,''),'Дж','Ж'),'дж','ж')
WHERE name_ru LIKE '%Дж%' OR name_ru LIKE '%дж%' OR name_kg LIKE '%Дж%' OR name_kg LIKE '%дж%'
   OR region_name_ru LIKE '%дж%' OR region_name_ru LIKE '%Дж%' OR district_name_ru LIKE '%дж%' OR district_name_ru LIKE '%Дж%';
-- 2) Aiyl-aimak name_kg -> authoritative Kyrgyz toponym (keyed by Russian name + district)
UPDATE cities SET name_kg='Садовой айыл аймагы' WHERE type='aiyl_aimak' AND name_ru='Садовский айылный аймак' AND coalesce(region_name_ru,'')='Чуйская область' AND coalesce(district_name_ru,'')='Московский район';
